<script setup lang="ts">
import { ArrowUpRight, CalendarDays } from 'lucide-vue-next'
definePageMeta({ layout: 'app' })
const api = useApi()
const { data: products } = await useAsyncData('portal-rental-products', () => api.request<any[]>('/catalog/products?category=Rentals').catch(() => []))
const { data: rentals, refresh } = await useAsyncData('portal-rentals', () => api.request<any[]>('/portal/rentals').catch(() => []))
const form = reactive({ productId: '', from: new Date(Date.now()+2*86400000).toISOString().slice(0,10), to: new Date(Date.now()+9*86400000).toISOString().slice(0,10) })
watch(products, (v) => { if (v?.length && !form.productId) form.productId = v[0]._id }, { immediate: true })
const saving = ref(false); const done = ref('')
async function reserve() { saving.value = true; try { const r = await api.request<any>('/portal/rentals', { method: 'POST', body: form }); done.value = r.ref; await refresh() } finally { saving.value = false } }
</script>
<template>
  <div><PortalHeader><template #eyebrow>Hardware as a service</template><template #title>Rentals.</template><template #subtitle>Reserve calibrated camera, acoustic or ILI kits for the run window.</template></PortalHeader>
    <div class="grid gap-5 xl:grid-cols-12"><div class="xl:col-span-5"><div class="rounded-xl border border-ink/12 bg-bone p-5"><p class="font-display text-[22px]">Reserve a kit</p><div class="mt-4 space-y-4"><div><label class="field-label">Kit</label><select v-model="form.productId" class="field"><option v-for="p in products" :key="p._id" :value="p._id">{{ p.name }} · {{ money(p.priceUsd) }}/wk</option></select></div><div class="grid grid-cols-2 gap-3"><div><label class="field-label">From</label><input v-model="form.from" type="date" class="field"></div><div><label class="field-label">To</label><input v-model="form.to" type="date" class="field"></div></div></div><button class="btn btn-dark mt-5 w-full" :disabled="saving" @click="reserve">{{ saving ? 'Reserving…' : 'Reserve kit' }}</button><p v-if="done" class="mt-3 rounded-lg bg-mint/20 p-3 text-[11px] text-mint-deep">Reservation {{ done }} created. Deposit is held, not charged.</p></div></div>
      <div class="xl:col-span-7"><div class="rounded-xl border border-ink/12 bg-bone"><div class="flex items-center justify-between border-b border-ink/10 px-4 py-3"><p class="font-display text-[18px]">Reservations</p><span class="font-mono text-[9px] text-ink/35">{{ rentals?.length || 0 }} total</span></div><div class="divide-y divide-ink/10"><div v-for="r in rentals" :key="r._id" class="flex items-center gap-3 px-4 py-4"><span class="flex size-9 items-center justify-center rounded-lg bg-signal/10 text-signal-deep"><CalendarDays :size="15" /></span><div class="min-w-0 flex-1"><p class="truncate text-[12.5px] font-medium">{{ r.productName }}</p><p class="font-mono text-[9px] uppercase tracking-[.06em] text-ink/35">{{ r.ref }} · {{ shortDate(r.from) }} → {{ shortDate(r.to) }}</p></div><span class="text-right"><span class="block font-mono text-[11px]">{{ money(r.total) }}</span><StatusPill :status="r.status" /></span></div></div><div v-if="!rentals?.length" class="p-8 text-center text-[13px] text-ink/40">No reservations yet.</div></div>
        <div class="mt-4 grid grid-cols-2 gap-3"><NuxtLink to="/rentals" class="rounded-xl border border-ink/12 p-4 hover:border-ink/30"><p class="font-mono text-[8px] uppercase text-ink/35">Catalog</p><p class="mt-2 font-display text-[20px]">Browse all kits <ArrowUpRight :size="13" class="inline" /></p></NuxtLink><div class="rounded-xl bg-ink p-4 text-bone"><p class="font-mono text-[8px] uppercase text-bone/35">Deposit policy</p><p class="mt-2 text-[11.5px] leading-relaxed text-bone/55">Fully refundable on return inspection. Damage is quoted before deduction.</p></div></div></div></div>
  </div>
</template>
